const { Window } = require('happy-dom');
const fs = require('fs');
const vm = require('vm');

const window = new Window({ url: 'http://localhost/' });
const html = fs.readFileSync('assets/app-template.index.html','utf8');
window.document.write(html);
window.document.close();
console.log('h1:', window.document.querySelector('h1')?.textContent);
console.log('has localStorage:', typeof window.localStorage);
window.localStorage.setItem('x','1');
console.log('ls get:', window.localStorage.getItem('x'));
console.log('location hash:', window.location.hash);

try {
  const ctx = window;
  vm.createContext(ctx);
  vm.runInContext('var g = (typeof document);', ctx);
  console.log('vm document ok, g=', ctx.g);
} catch(e){ console.log('vm err', e.message); }

const { setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '..', '..');
const INDEX_HTML = path.join(ROOT, 'index.html');
const APP_JS = path.join(ROOT, 'js', 'app.js');

// A fresh happy-dom window loaded with the production index.html and js/app.js.
// Each scenario starts from a clean window; reloads re-seed localStorage and hash.
class TodoWorld {
  constructor({ attach, parameters }) {
    this.attach = attach;
    this.parameters = parameters;
    this.window = null;
    this.document = null;
  }

  // Load the app into a fresh window. `seed` is a plain object of localStorage
  // keys to values; `hash` is a route fragment like '#/active'.
  loadApp({ seed, hash } = {}) {
    const route = hash || '';
    const window = new Window({ url: 'http://localhost/' + route });
    // Self-references so production code that uses `window` resolves.
    window.window = window;
    window.self = window;
    window.globalThis = window;

    if (seed) {
      for (const [k, v] of Object.entries(seed)) {
        window.localStorage.setItem(k, v);
      }
    }

    const html = fs.readFileSync(INDEX_HTML, 'utf8');
    window.document.write(html);
    window.document.close();

    if (fs.existsSync(APP_JS)) {
      const code = fs.readFileSync(APP_JS, 'utf8');
      const sandbox = window;
      try {
        vm.createContext(sandbox);
      } catch (e) {
        // already a context
      }
      vm.runInContext(code, sandbox, { filename: 'js/app.js' });
    }

    this.window = window;
    this.document = window.document;

    // Fire lifecycle events the app may listen for.
    this.window.document.dispatchEvent(new this.window.Event('DOMContentLoaded'));
    this.window.dispatchEvent(new this.window.Event('load'));
  }

  // Re-create the window preserving persisted storage and the current route.
  reload() {
    const store = {};
    const ls = this.window.localStorage;
    for (let i = 0; i < ls.length; i++) {
      const k = ls.key(i);
      store[k] = ls.getItem(k);
    }
    const hash = this.window.location.hash;
    this.loadApp({ seed: store, hash });
  }

  // --- DOM interaction helpers ---

  get el() {
    return this.document;
  }

  newTodoInput() {
    return this.document.querySelector('.new-todo');
  }

  mainSection() {
    return this.document.querySelector('.main');
  }

  footer() {
    return this.document.querySelector('.footer');
  }

  toggleAll() {
    return this.document.getElementById('toggle-all');
  }

  clearCompletedBtn() {
    return this.document.querySelector('.clear-completed');
  }

  countEl() {
    return this.document.querySelector('.todo-count');
  }

  allLis() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  visibleLis() {
    return this.allLis().filter((li) => !li.hidden);
  }

  liFor(title) {
    return this.allLis().find(
      (li) => (li.querySelector('label') || {}).textContent === title
    );
  }

  visibleLiFor(title) {
    return this.visibleLis().find(
      (li) => (li.querySelector('label') || {}).textContent === title
    );
  }

  labelOf(li) {
    return (li && (li.querySelector('label') || {}).textContent) || '';
  }

  // Create a todo through the real new-todo input path.
  createTodo(title) {
    const input = this.newTodoInput();
    input.value = title;
    input.dispatchEvent(
      new this.window.Event('input', { bubbles: true })
    );
    this.pressKey(input, 'Enter');
  }

  pressKey(el, key) {
    const keyCode = key === 'Enter' ? 13 : key === 'Escape' ? 27 : 0;
    const ev = new this.window.KeyboardEvent('keydown', {
      key,
      keyCode,
      which: keyCode,
      bubbles: true,
      cancelable: true,
    });
    el.dispatchEvent(ev);
    const pe = new this.window.KeyboardEvent('keypress', {
      key,
      keyCode,
      which: keyCode,
      bubbles: true,
      cancelable: true,
    });
    el.dispatchEvent(pe);
  }

  setRoute(route) {
    // route is like '#/active' or '' for blank
    if (route === '') {
      this.window.location.hash = '';
    } else {
      this.window.location.hash = route;
    }
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  // --- localStorage helpers ---

  storageGet(key) {
    return this.window.localStorage.getItem(key);
  }
}

setWorldConstructor(TodoWorld);

module.exports = { TodoWorld };

const {
  Given,
  When,
  Then,
} = require('@cucumber/cucumber');
const assert = require('assert');

// --- App loading / seeding ---

Given('the todo app is freshly loaded with no todos', function () {
  this.loadApp();
});

Given('the todo app has the todo {string}', function (title) {
  this.loadApp();
  this.createTodo(title);
});

Given('the todo app has the todos {string} and {string}', function (a, b) {
  this.loadApp();
  this.createTodo(a);
  this.createTodo(b);
});

Given(
  'the todo app has the todos {string}, {string}, and {string}',
  function (a, b, c) {
    this.loadApp();
    this.createTodo(a);
    this.createTodo(b);
    this.createTodo(c);
  }
);

Given(
  'the todo app has {int} active todos and {int} completed todos',
  function (active, completed) {
    this.loadApp();
    const total = active + completed;
    for (let i = 1; i <= total; i++) {
      this.createTodo('Todo ' + i);
    }
    if (completed > 0) {
      // mark the last `completed` todos as complete
      const lis = this.allLis();
      for (let i = 0; i < completed; i++) {
        const li = lis[total - 1 - i];
        const toggle = li.querySelector('.toggle');
        toggle.checked = true;
        toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
      }
    }
  }
);

// --- State preconditions ---

Given('the todo {string} is marked as complete', function (title) {
  const li = this.liFor(title);
  assert(li, 'no todo found titled "' + title + '"');
  const toggle = li.querySelector('.toggle');
  if (!toggle.checked) {
    toggle.checked = true;
    toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
  }
});

Given('the todo {string} is in editing mode', function (title) {
  const li = this.liFor(title);
  assert(li, 'no todo found titled "' + title + '"');
  const label = li.querySelector('label');
  label.dispatchEvent(
    new this.window.MouseEvent('dblclick', { bubbles: true })
  );
});

Given('the route is {string}', function (route) {
  this.setRoute(route);
});

Given('the route is blank', function () {
  this.setRoute('');
});

// --- New todo actions ---

When('I enter {string} in the new-todo input', function (text) {
  const input = this.newTodoInput();
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press the Enter key in the new-todo input', function () {
  this.pressKey(this.newTodoInput(), 'Enter');
});

// --- Editing actions ---

When('I enter {string} in the edit field of the todo {string}', function (text, title) {
  const li = this.liFor(title);
  const edit = li.querySelector('.edit');
  edit.value = text;
  edit.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('I press the Enter key in the edit field', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert(edit, 'no active edit field found');
  this.pressKey(edit, 'Enter');
});

When('I blur the edit field of the todo {string}', function (title) {
  const li = this.liFor(title);
  const edit = li.querySelector('.edit');
  edit.dispatchEvent(new this.window.FocusEvent('blur', { bubbles: true }));
});

When('I press the Escape key in the edit field', function () {
  const edit = this.document.querySelector('.todo-list li.editing .edit');
  assert(edit, 'no active edit field found');
  this.pressKey(edit, 'Escape');
});

When('I double-click the label of the todo {string}', function (title) {
  const li = this.liFor(title);
  const label = li.querySelector('label');
  label.dispatchEvent(new this.window.MouseEvent('dblclick', { bubbles: true }));
});

// --- Toggle / mark-all / destroy / clear actions ---

When('I check the toggle of the todo {string}', function (title) {
  const toggle = this.liFor(title).querySelector('.toggle');
  toggle.checked = true;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I uncheck the toggle of the todo {string}', function (title) {
  const toggle = this.liFor(title).querySelector('.toggle');
  toggle.checked = false;
  toggle.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I check the mark-all checkbox', function () {
  const cb = this.toggleAll();
  cb.checked = true;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I uncheck the mark-all checkbox', function () {
  const cb = this.toggleAll();
  cb.checked = false;
  cb.dispatchEvent(new this.window.Event('change', { bubbles: true }));
});

When('I click the destroy button of the todo {string}', function (title) {
  const btn = this.liFor(title).querySelector('.destroy');
  btn.dispatchEvent(new this.window.MouseEvent('click', { bubbles: true }));
});

When('I click the clear-completed button', function () {
  this.clearCompletedBtn().dispatchEvent(
    new this.window.MouseEvent('click', { bubbles: true })
  );
});

When('the page reloads', function () {
  this.reload();
});

// --- Assertions: new-todo input ---

Then('the new-todo input has focus', function () {
  assert.strictEqual(
    this.document.activeElement,
    this.newTodoInput(),
    'new-todo input is not focused'
  );
});

Then('the new-todo input is empty', function () {
  assert.strictEqual(this.newTodoInput().value, '');
});

// --- Assertions: todo list ---

Then('the todo list shows {int} todo(s)', function (n) {
  assert.strictEqual(this.visibleLis().length, n, this.describeList());
});

Then('the todo list shows the todo {string}', function (title) {
  assert(this.visibleLiFor(title), 'todo "' + title + '" not visible: ' + this.describeList());
});

Then('the todo list does not show the todo {string}', function (title) {
  assert(
    !this.visibleLiFor(title),
    'todo "' + title + '" unexpectedly visible: ' + this.describeList()
  );
});

Then(
  'the todo list shows the todos in the order {string}, {string}',
  function (a, b) {
    const order = this.visibleLis().map((li) => this.labelOf(li));
    assert.deepStrictEqual(order, [a, b], this.describeList());
  }
);

// --- Assertions: completion state ---

Then('the todo {string} is marked as complete', function (title) {
  const li = this.liFor(title);
  assert(li, 'no todo "' + title + '"');
  assert(li.classList.contains('completed'), 'todo "' + title + '" not complete');
});

Then('the todo {string} is not marked as complete', function (title) {
  const li = this.liFor(title);
  assert(li, 'no todo "' + title + '"');
  assert(
    !li.classList.contains('completed'),
    'todo "' + title + '" unexpectedly complete'
  );
});

Then('the mark-all checkbox is checked', function () {
  assert(this.toggleAll().checked, 'mark-all checkbox not checked');
});

Then('the mark-all checkbox is not checked', function () {
  assert(!this.toggleAll().checked, 'mark-all checkbox unexpectedly checked');
});

// --- Assertions: editing ---

Then('the todo {string} is in editing mode', function (title) {
  const li = this.liFor(title);
  assert(li.classList.contains('editing'), 'todo "' + title + '" not in editing mode');
});

Then('the todo {string} is not in editing mode', function (title) {
  const li = this.liFor(title);
  assert(!li.classList.contains('editing'), 'todo "' + title + '" still in editing mode');
});

Then('the edit field of the todo {string} is focused', function (title) {
  const li = this.liFor(title);
  const edit = li.querySelector('.edit');
  assert.strictEqual(this.document.activeElement, edit, 'edit field not focused');
});

Then('the edit field of the todo {string} contains the text {string}', function (title, text) {
  const li = this.liFor(title);
  assert.strictEqual(li.querySelector('.edit').value, text);
});

// --- Assertions: visibility ---

Then('the main section is hidden', function () {
  assert(this.mainSection().hidden, 'main section not hidden');
});

Then('the main section is visible', function () {
  assert(!this.mainSection().hidden, 'main section hidden');
});

Then('the footer is hidden', function () {
  assert(this.footer().hidden, 'footer not hidden');
});

Then('the footer is visible', function () {
  assert(!this.footer().hidden, 'footer hidden');
});

Then('the clear-completed button is hidden', function () {
  assert(this.clearCompletedBtn().hidden, 'clear-completed not hidden');
});

Then('the clear-completed button is visible', function () {
  assert(!this.clearCompletedBtn().hidden, 'clear-completed hidden');
});

// --- Assertions: counter ---

Then('the item counter reads {string}', function (phrase) {
  const actual = (this.countEl().textContent || '').replace(/\s+/g, ' ').trim();
  assert.strictEqual(actual, phrase, 'counter read "' + actual + '"');
});

Then('the item counter shows the number {int} wrapped in a strong element', function (n) {
  const strong = this.countEl().querySelector('strong');
  assert(strong, 'no strong element in counter');
  assert.strictEqual(strong.textContent, String(n));
});

// --- Assertions: localStorage persistence ---

Then('localStorage holds the key {string}', function (key) {
  assert(this.storageGet(key) !== null, 'localStorage missing key "' + key + '"');
});

Then('the value of the {string} key is a JSON array with {int} items', function (key, n) {
  const arr = JSON.parse(this.storageGet(key));
  assert(Array.isArray(arr), 'value of "' + key + '" is not an array');
  assert.strictEqual(arr.length, n, 'array has ' + arr.length + ' items');
});

Then(
  'every item in the {string} localStorage key has the keys {string}, {string}, and {string}',
  function (key, k1, k2, k3) {
    const arr = JSON.parse(this.storageGet(key));
    for (const item of arr) {
      assert(
        item[k1] !== undefined && item[k2] !== undefined && item[k3] !== undefined,
        'an item is missing a required key'
      );
    }
  }
);

Then('the persisted todo {string} has completed set to true', function (title) {
  const arr = JSON.parse(this.storageGet('todos-vanilla'));
  const item = arr.find((i) => i.title === title);
  assert(item, 'no persisted todo "' + title + '"');
  assert.strictEqual(item.completed, true);
});

Then('the ids in the {string} localStorage key are unique', function (key) {
  const arr = JSON.parse(this.storageGet(key));
  const ids = arr.map((i) => i.id);
  assert.strictEqual(new Set(ids).size, ids.length, 'ids are not unique');
});

// --- Assertions: routing ---

Then('the route is {string}', function (route) {
  assert.strictEqual(this.window.location.hash, route, 'route was "' + this.window.location.hash + '"');
});

Then('the All filter link is selected', function () {
  const a = this.document.querySelector('.filters a[href="#/"]');
  assert(a && a.classList.contains('selected'), 'All filter not selected');
});

Then('the Active filter link is selected', function () {
  const a = this.document.querySelector('.filters a[href="#/active"]');
  assert(a && a.classList.contains('selected'), 'Active filter not selected');
});

Then('the Completed filter link is selected', function () {
  const a = this.document.querySelector('.filters a[href="#/completed"]');
  assert(a && a.classList.contains('selected'), 'Completed filter not selected');
});

