const { BeforeStep } = require('@cucumber/cucumber');

const TERMINAL = new Set(['Given', 'When', 'Then']);

// Find the Gherkin steps array that contains the step with the given AST id.
function stepsForAstId(doc, astId) {
  if (!doc || !doc.feature) return null;
  function searchChildren(children) {
    for (const child of children) {
      if (child.scenario) {
        const steps = child.scenario.steps || [];
        if (steps.some((s) => s.id === astId)) return steps;
      }
      if (child.background && (child.background.steps || []).some((s) => s.id === astId)) {
        return child.background.steps;
      }
      if (child.rule && child.rule.children) {
        const r = searchChildren(child.rule.children);
        if (r) return r;
      }
    }
    return null;
  }
  return searchChildren(doc.feature.children);
}

// Resolve the effective keyword (Given/When/Then) for a pickle step, folding
// And/But back to the preceding terminal keyword.
function resolveKeyword(doc, pickleStep) {
  const ids = pickleStep.astNodeIds || [];
  for (const id of ids) {
    const steps = stepsForAstId(doc, id);
    if (steps) {
      const idx = steps.findIndex((s) => s.id === id);
      if (idx >= 0) {
        for (let j = idx; j >= 0; j--) {
          const kw = (steps[j].keyword || '').trim();
          if (TERMINAL.has(kw)) return kw;
        }
        return 'Given'; // background steps default to Given
      }
    }
  }
  return null;
}

BeforeStep(function ({ gherkinDocument, pickleStep }) {
  this._stepKeyword = resolveKeyword(gherkinDocument, pickleStep);
});

