(function () {
	'use strict';

	var STORAGE_KEY = 'todos-vanilla';
	var todos = [];
	var filter = 'all';

	var newTodoEl, todoListEl, mainEl, footerEl, toggleAllEl, countEl, clearCompletedEl, filterLinks;

	function uid() {
		return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
	}

	/** @planks("the todo app is freshly loaded with no todos") */
	function load() {
		try {
			var raw = localStorage.getItem(STORAGE_KEY);
			var data = raw ? JSON.parse(raw) : [];
			todos = Array.isArray(data) ? data : [];
		} catch (e) {
			todos = [];
		}
	}

	/** @planks("Todos are persisted to localStorage under the key {string}") */
	function save() {
		localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
	}

	function setFilterFromHash() {
		var h = location.hash;
		if (h === '#/active') {
			filter = 'active';
		} else if (h === '#/completed') {
			filter = 'completed';
		} else {
			filter = 'all';
		}
	}

	function visibleTodos() {
		return todos.filter(function (t) {
			if (filter === 'active') return !t.completed;
			if (filter === 'completed') return t.completed;
			return true;
		});
	}

	function findTodo(id) {
		return todos.filter(function (t) { return t.id === id; })[0];
	}

	/** @planks("the todo list shows {int} todo(s)") */
	/** @planks("the todo list shows the todo {string}") */
	/** @planks("the main section is hidden") */
	/** @planks("the main section is visible") */
	/** @planks("the footer is hidden") */
	/** @planks("the footer is visible") */
	/** @planks("the item counter reads {string}") */
	/** @planks("the All filter link is selected") */
	/** @planks("the Active filter link is selected") */
	/** @planks("the Completed filter link is selected") */
	/** @planks("the mark-all checkbox is checked") */
	/** @planks("the mark-all checkbox is not checked") */
	/** @planks("the clear-completed button is hidden") */
	/** @planks("the clear-completed button is visible") */
	function render() {
		todoListEl.innerHTML = '';
		visibleTodos().forEach(function (t) {
			var li = document.createElement('li');
			li.setAttribute('data-id', t.id);
			if (t.completed) {
				li.classList.add('completed');
			}

			var view = document.createElement('div');
			view.className = 'view';

			var toggle = document.createElement('input');
			toggle.className = 'toggle';
			toggle.type = 'checkbox';
			toggle.checked = t.completed;
			toggle.addEventListener('change', function () { onToggle(t.id); });

			var label = document.createElement('label');
			label.textContent = t.title;
			label.addEventListener('dblclick', function () { startEdit(t.id); });

			var destroy = document.createElement('button');
			destroy.className = 'destroy';
			destroy.addEventListener('click', function () { onDestroy(t.id); });

			view.appendChild(toggle);
			view.appendChild(label);
			view.appendChild(destroy);

			var edit = document.createElement('input');
			edit.className = 'edit';
			edit.value = t.title;
			edit.addEventListener('keydown', function (e) { onEditKey(t.id, e); });
			edit.addEventListener('blur', function () { onEditBlur(t.id); });

			li.appendChild(view);
			li.appendChild(edit);
			todoListEl.appendChild(li);
		});

		var activeCount = todos.filter(function (t) { return !t.completed; }).length;
		countEl.innerHTML = '<strong>' + activeCount + '</strong> ' + (activeCount === 1 ? 'item' : 'items') + ' left';

		if (todos.length === 0) {
			mainEl.setAttribute('hidden', '');
			footerEl.setAttribute('hidden', '');
		} else {
			mainEl.removeAttribute('hidden');
			footerEl.removeAttribute('hidden');
		}

		var anyCompleted = todos.some(function (t) { return t.completed; });
		if (anyCompleted) {
			clearCompletedEl.removeAttribute('hidden');
		} else {
			clearCompletedEl.setAttribute('hidden', '');
		}

		toggleAllEl.checked = todos.length > 0 && todos.every(function (t) { return t.completed; });

		Array.prototype.forEach.call(filterLinks, function (a) {
			var href = a.getAttribute('href');
			var selected = (href === '#/' && filter === 'all') ||
				(href === '#/active' && filter === 'active') ||
				(href === '#/completed' && filter === 'completed');
			if (selected) {
				a.classList.add('selected');
			} else {
				a.classList.remove('selected');
			}
		});
	}

	/** @planks("I press the Enter key in the new-todo input") */
	/** @planks("the new-todo input is empty") */
	function onNewTodoKey(e) {
		if (e.key !== 'Enter' && e.keyCode !== 13) {
			return;
		}
		var v = newTodoEl.value.trim();
		if (!v) {
			return;
		}
		todos.push({ id: uid(), title: v, completed: false });
		save();
		newTodoEl.value = '';
		render();
	}

	/** @planks("I check the toggle of the todo {string}") */
	/** @planks("I uncheck the toggle of the todo {string}") */
	/** @planks("the todo {string} is marked as complete") */
	/** @planks("the todo {string} is not marked as complete") */
	function onToggle(id) {
		var t = findTodo(id);
		if (!t) {
			return;
		}
		t.completed = !t.completed;
		save();
		render();
	}

	/** @planks("I click the destroy button of the todo {string}") */
	function onDestroy(id) {
		todos = todos.filter(function (t) { return t.id !== id; });
		save();
		render();
	}

	/** @planks("Double-clicking a todo's label opens editing mode") */
	/** @planks("the todo {string} is in editing mode") */
	/** @planks("the edit field of the todo {string} is focused") */
	/** @planks("the edit field of the todo {string} contains the text {string}") */
	function startEdit(id) {
		var li = todoListEl.querySelector('[data-id="' + id + '"]');
		if (!li) {
			return;
		}
		li.classList.add('editing');
		var edit = li.querySelector('.edit');
		if (edit) {
			edit.focus();
		}
	}

	/** @planks("I press the Enter key in the edit field") */
	/** @planks("I press the Escape key in the edit field") */
	/** @planks("I blur the edit field of the todo {string}") */
	function onEditKey(id, e) {
		if (e.key === 'Enter' || e.keyCode === 13) {
			saveEdit(id);
		} else if (e.key === 'Escape' || e.keyCode === 27) {
			cancelEdit(id);
		}
	}

	function onEditBlur(id) {
		var li = todoListEl.querySelector('[data-id="' + id + '"]');
		if (!li || !li.classList.contains('editing')) {
			return;
		}
		saveEdit(id);
	}

	function saveEdit(id) {
		var li = todoListEl.querySelector('[data-id="' + id + '"]');
		if (!li || !li.classList.contains('editing')) {
			return;
		}
		var edit = li.querySelector('.edit');
		var v = edit.value.trim();
		li.classList.remove('editing');
		if (!v) {
			onDestroy(id);
			return;
		}
		var t = findTodo(id);
		if (t) {
			t.title = v;
			save();
		}
		var label = li.querySelector('label');
		if (label) {
			label.textContent = v;
		}
	}

	function cancelEdit(id) {
		var li = todoListEl.querySelector('[data-id="' + id + '"]');
		if (!li) {
			return;
		}
		li.classList.remove('editing');
		var t = findTodo(id);
		var edit = li.querySelector('.edit');
		if (edit && t) {
			edit.value = t.title;
		}
	}

	/** @planks("I check the mark-all checkbox") */
	/** @planks("I uncheck the mark-all checkbox") */
	function onToggleAll() {
		var checked = toggleAllEl.checked;
		todos.forEach(function (t) { t.completed = checked; });
		save();
		render();
	}

	/** @planks("I click the clear-completed button") */
	function onClearCompleted() {
		todos = todos.filter(function (t) { return !t.completed; });
		save();
		render();
	}

	/** @planks("The All route shows every todo") */
	/** @planks("The active route shows only active todos") */
	/** @planks("The completed route shows only completed todos") */
	function onHashChange() {
		setFilterFromHash();
		render();
	}

	/** @planks("the new-todo input has focus") */
	function init() {
		newTodoEl = document.querySelector('.new-todo');
		todoListEl = document.querySelector('.todo-list');
		mainEl = document.querySelector('.main');
		footerEl = document.querySelector('.footer');
		toggleAllEl = document.getElementById('toggle-all');
		countEl = document.querySelector('.todo-count');
		clearCompletedEl = document.querySelector('.clear-completed');
		filterLinks = document.querySelectorAll('.filters a');

		load();
		setFilterFromHash();
		render();

		newTodoEl.addEventListener('keydown', onNewTodoKey);
		toggleAllEl.addEventListener('change', onToggleAll);
		clearCompletedEl.addEventListener('click', onClearCompleted);
		window.addEventListener('hashchange', onHashChange);

		newTodoEl.focus();
	}

	init();
})();

