arguments.content:
const fs = require('fs');
const app = fs.readFileSync('js/app.js', 'utf8');
const steps = fs.readFileSync('features/support/steps.js', 'utf8');
const planks = [...app.matchAll(/@planks\("([^"]*)"\)/g)].map((m) => m[1]);
const pats = new Set();
const re = /(?:Given|When|Then)\(\s*['"]([^'"]+)['"]/g;
let m;
while ((m = re.exec(steps))) {
  pats.add(m[1]);
}
console.log('planks count:', planks.length);
console.log('patterns count:', pats.size);
const bad = planks.filter((p) => !pats.has(p));
console.log('planks not matching any pattern:', bad);
const seen = new Set();
const dups = [];
for (const p of planks) {
  if (seen.has(p)) dups.push(p);
  seen.add(p);
}
console.log('duplicate planks:', dups);
// orphan patterns: defined but never used by a plank? (not required; just info)
